    def williams_r(self, high, low, close, period):
        highest_high = high.rolling(window=period).max()
        lowest_low = low.rolling(window=period).min()
        return -100 * ((highest_high - close) / (highest_high - lowest_low))

    def mfi(self, high, low, close, volume, period):
        typical_price = (high + low + close) / 3
        money_flow = typical_price * volume
        positive_flow = money_flow.copy()
        positive_flow[money_flow < 0] = 0
        negative_flow = abs(money_flow.copy())
        negative_flow[money_flow > 0] = 0
        money_ratio = positive_flow.rolling(window=period).sum() / negative_flow.rolling(window=period).sum()
        return 100 - (100 / (1 + money_ratio))

